from datetime import datetime
import numpy as np

class MovieBookingSystem:
    SEAT_EMPTY = 0
    SEAT_BOOKED = 1

    def __init__(self):
        self.movies = []

    def add_movie(self, name, price, start_time, end_time, n):
        movie = self._create_movie(name, price, start_time, end_time, n)
        self.movies.append(movie)

    def _create_movie(self, name, price, start_time, end_time, n):
        return {
            'name': name,
            'price': price,
            'start_time': datetime.strptime(start_time, '%H:%M'),
            'end_time': datetime.strptime(end_time, '%H:%M'),
            'seats': np.zeros((n, n), dtype=int)
        }

    def book_ticket(self, name, seats_to_book):
        movie = self._find_movie_by_name(name)
        if movie is None:
            return "Movie not found."

        return self._book_seats(movie, seats_to_book)

    def _find_movie_by_name(self, name):
        for movie in self.movies:
            if movie['name'] == name:
                return movie
        return None

    def _book_seats(self, movie, seats_to_book):
        for row, col in seats_to_book:
            if movie['seats'][row][col] != self.SEAT_EMPTY:
                return "Booking failed."
        for row, col in seats_to_book:
            movie['seats'][row][col] = self.SEAT_BOOKED
        return "Booking success."

    def available_movies(self, start_time, end_time):
        start_dt = self._parse_time(start_time)
        end_dt = self._parse_time(end_time)

        return [
            movie['name']
            for movie in self.movies
            if self._is_movie_available(movie, start_dt, end_dt)
        ]

    def _parse_time(self, time_str):
        return datetime.strptime(time_str, '%H:%M')

    def _is_movie_available(self, movie, start_time, end_time):
        return start_time <= movie['start_time'] and movie['end_time'] <= end_time
